def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    stack = []
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.append(char)
            if stack[-1] == '(':
                groups.append(''.join(stack))
                stack = []
    return groups

